    public static int ttPush(emon.Port.Cells c, byte[] b) {
        // The bytes of an ASCII text blob, as code points.
        int n = emon.Port.blobLen(b);
        int i = 0;
        while (i < n) {
            int v = emon.Port.blobU8(b, i);
            emon.Port.cellsPush(c, v);
            i += 1;
        }
        return n;
    }
