    public static int ttFoundAt(emon.Transcriptctx.Tr t, emon.Port.Cells k, int at, int cnt) {
        // The place of the entry a request finds, or -1.
        int e = Transcript.trFind(t, k, at, cnt);
        if (e < 0) {
            return -1;
        }
        return Transcript.trEN(t, e);
    }
    public static int ttFound(emon.Transcriptctx.Tr t, emon.Port.Cells k) {
        return ttFoundAt(t, k, 0, 4);
    }
    public static int ttTaken(emon.Transcriptctx.Tr t, emon.Port.Cells k) {
        // The place of the entry a request takes (and marks used), or -1.
        int e = Transcript.trTake(t, k, 0, 4);
        if (e < 0) {
            return -1;
        }
        return Transcript.trEN(t, e);
    }
    public static int ttPair(emon.Port.Cells c, int index, int length) {
        emon.Port.cellsPush(c, index);
        emon.Port.cellsPush(c, length);
        return 0;
    }
    public static void testAReplayIsGivenTheInputsTheRecordingSaw() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        emon.Port.Cells want = emon.Port.newCells();
        StringBuilder out = emon.Testport.newText();
        Transcript.trAddInput(t, 0, 5);
        ttPair(want, 0, 5);
        emon.Testport.assertEq(Transcript.trCheckInputs(t, want, out), 0, "the same");
        emon.Testport.assertText(out, "", "nothing said");
    }
