    public static void testARequestIsFoundByTheWholeRecord() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        emon.Port.Cells k = emon.Port.newCells();
        ttEntry(t, 0, Transcript.tkRender(), 1, 10, 0);
        ttEntry(t, 0, Transcript.tkOcr(), 2, 20, 0);
        ttEntry(t, 1, Transcript.tkRender(), 3, 30, 0);
        emon.Testport.assertEq(Transcript.trIndex(t), 0, "indexed");
        ttKey(k, Transcript.tkOcr(), 2, 20);
        emon.Testport.assertEq(ttFound(t, k), 1, "the second entry is found by its place");
        ttKey(k, Transcript.tkRender(), 3, 30);
        emon.Testport.assertEq(ttFound(t, k), 2, "the third");
        ttKey(k, Transcript.tkRender(), 3, 31);
        emon.Testport.assertEq(Transcript.trFind(t, k, 0, 4), -1, "one cell different is a miss");
        ttKey(k, Transcript.tkDecode(), 3, 30);
        emon.Testport.assertEq(Transcript.trFind(t, k, 0, 4), -1, "another kind is a miss");
        ttKey(k, Transcript.tkRender(), 4, 30);
        emon.Testport.assertEq(Transcript.trFind(t, k, 0, 4), -1, "another id is a miss");
        ttKey(k, Transcript.tkRender(), 3, 30);
        emon.Testport.assertEq(Transcript.trFind(t, k, 0, 3), -1, "a shorter record is a miss");
        emon.Port.cellsPush(k, 9);
        emon.Testport.assertEq(Transcript.trFind(t, k, 0, 5), -1, "a longer record is a miss");
    }
