    public static void testOfTwoEntriesOfOneRequestTheLaterAnswers() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        emon.Port.Cells k = emon.Port.newCells();
        ttEntry(t, 0, Transcript.tkOcr(), 5, 50, 0);
        ttEntry(t, 0, Transcript.tkOcr(), 6, 60, 0);
        ttEntry(t, 3, Transcript.tkOcr(), 5, 50, 0);
        Transcript.trIndex(t);
        ttKey(k, Transcript.tkOcr(), 5, 50);
        int e = Transcript.trTake(t, k, 0, 4);
        emon.Testport.assertEq(Transcript.trEN(t, e), 2, "the later");
        emon.Testport.assertEq(Transcript.trERound(t, e), 3, "its round");
        ttKey(k, Transcript.tkOcr(), 6, 60);
        emon.Testport.assertEq(ttTaken(t, k), 1, "the other request");
        emon.Testport.assertEq(Transcript.trUnused(t), 1, "the earlier of the two was never asked for");
    }
    public static void testTheEntriesNobodyAskedForAreCounted() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        emon.Port.Cells k = emon.Port.newCells();
        StringBuilder out = emon.Testport.newText();
        ttEntry(t, 0, Transcript.tkRender(), 1, 10, 0);
        ttEntry(t, 0, Transcript.tkRender(), 2, 20, 0);
        ttEntry(t, 0, Transcript.tkRender(), 3, 30, 0);
        Transcript.trIndex(t);
        emon.Testport.assertEq(Transcript.trUnused(t), 3, "all three");
        ttKey(k, Transcript.tkRender(), 2, 20);
        emon.Testport.assertThat(Transcript.trTake(t, k, 0, 4) >= 0, "one asked");
        emon.Testport.assertEq(Transcript.trUnused(t), 2, "two left");
        Transcript.trTake(t, k, 0, 4);
        emon.Testport.assertEq(Transcript.trUnused(t), 2, "asking twice counts once");
        ttKey(k, Transcript.tkRender(), 2, 21);
        emon.Testport.assertEq(Transcript.trTake(t, k, 0, 4), -1, "a miss marks nothing");
        emon.Testport.assertEq(Transcript.trUnused(t), 2, "still two");
        Transcript.trUnusedMsg(t, out);
        emon.Testport.assertText(out, "2 recorded entries were never asked for", "the sentence of transcript-bad");
    }
    public static void testFindDoesNotMarkAndTakeDoes() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        emon.Port.Cells k = emon.Port.newCells();
        ttEntry(t, 0, Transcript.tkRender(), 1, 10, 0);
        Transcript.trIndex(t);
        ttKey(k, Transcript.tkRender(), 1, 10);
        emon.Testport.assertThat(Transcript.trFind(t, k, 0, 4) >= 0, "found");
        emon.Testport.assertEq(Transcript.trUnused(t), 1, "find leaves it");
        emon.Testport.assertThat(Transcript.trTake(t, k, 0, 4) >= 0, "taken");
        emon.Testport.assertEq(Transcript.trUnused(t), 0, "take marks it");
    }
