    public static int ttMany(int emonT, int n) {
        // n entries of distinct requests, every one found by its own record and no other.
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        emon.Port.Cells k = emon.Port.newCells();
        int i = 0;
        while (i < n) {
            ttEntry(t, i / 7, Transcript.tkOcr(), i + 1, i * 3, 0);
            i += 1;
        }
        Transcript.trIndex(t);
        i = 0;
        while (i < n) {
            ttKey(k, Transcript.tkOcr(), i + 1, i * 3);
            emon.Testport.assertEqAt(ttTaken(t, k), i, "found at its own place", i);
            ttKey(k, Transcript.tkOcr(), i + 1, (i * 3) + 1);
            emon.Testport.assertEqAt(ttFound(t, k), -1, "a neighbour is a miss", i);
            i += 1;
        }
        emon.Testport.assertEq(Transcript.trUnused(t), 0, "all asked for");
        return 0;
    }
